import math
from typing import List

def minimumArrayLength(nums: List[int]) -> int:
    positives = [x for x in nums if x > 0]
    P = len(positives)
    L = len(nums)

    if P == 0:
        return L

    # Check if all positives are the same value
    all_same = True
    for i in range(1, P):
        if positives[i] != positives[0]:
            all_same = False
            break

    if all_same:
        return L - (P // 2)

    # Calculate the GCD of all positive integers
    g = positives[0]
    for i in range(1, P):
        g = math.gcd(g, positives[i])

    if g == 1:
        # If gcd is 1 and not all are same, we can always reduce to length L - (P-1)
        return L - (P - 1)
    else:
        # All numbers are multiples of some g > 1.
        # We can perform non-zero results as long as there is a number k*g where k > 1.
        # Every such "extra" multiple can be used to either produce another g (non-zero)
        # or eliminate itself and leave the count of g's unchanged (zero result).
        c_g = sum(1 for x in positives if x == g)
        # K is the total number of operations. 
        # We use one operation per "extra" multiple (P - c_g),
        # and then we are left with c_g copies of g, which provide floor(c_g / 2) ops.
        K = (P - c_g) + (c_g // 2)
        return L - min(P - 1, K)

