from typing import List

def longestEqualSubarray(nums: List[int], k: int) -> int:
    ans = 0
    # Dictionary to store the left boundary for each unique number
    pos_map = {}
    # Lists to store indices of each occurrence of numbers
    indices = {}

    for i, x in enumerate(nums):
        if x not in indices:
            indices[x] = []
        indices[x].append(i)

    for x in indices:
        idx_list = indices[x]
        left = 0
        # Sliding window over the indices of the same number
        for right in range(len(idx_list)):
            # The distance between first and last element must be <= k + (count - 1)
            # Actually: (Total elements from start to end) - (Count of x) <= k
            # Which is: (idx_list[right] - idx_list[left] + 1) - (right - left + 1) <= k
            # Simplified: idx_list[right] - idx_list[left] <= k
            while idx_list[right] - idx_list[left] > k:
                left += 1
            ans = max(ans, right - left + 1)

    return ans
