def shortestBeautifulSubstring(s: str, k: int) -> str:
    n = len(s)
    min_len = float('inf')
    best_sub = ""

    # 遍歷所有可能的子字串
    for i in range(n):
        count = 0
        for j in range(i, n):
            if s[j] == '1':
                count += 1

            # 當 1 的數量剛好等於 k 時
            if count == k:
                current_len = j - i + 1
                substring = s[i : j + 1]

                # 更新最短長度或在長度相等時比較字典序
                if current_len < min_len:
                    min_len = current_len
                    best_sub = substring
                elif current_len == min_len:
                    if substring < best_sub:
                        best_sub = substring
                # 因為繼續往後擴充，1 的數量只會增加，所以此處可直接 break 往內層迴圈
                break

    return best_sub
