def sortVowels(s: str) -> str:
    vowels_set = set("aeiouAEIOU")
    vowels = sorted([char for char in s if char in vowels_set])
    res = list(s)
    v_idx = 0
    for i in range(len(res)):
        if res[i] in vowels_set:
            res[i] = vowels[v_idx]
            v_idx += 1
    return "".join(res)
